export declare function upProbability(rawYes: bigint | string | null | undefined, decimals: number | undefined): number | null;
/** The Up probability as a whole-percent integer (e.g. `0.546` → `55`). */
export declare function upPercent(rawYes: bigint | string | null | undefined, decimals: number | undefined): number | null;
